import scipy.spatial as sp
pts={'A':(14,0),'B':(17,3),'C':(9,5),'D':(10,6),'E':(13,6),'F':(15,8),'G':(17,8)}
h=sp.ConvexHull(list(pts.values())); [(list(pts.keys())[i],pts[list(pts.keys())[i]]) for i in h.vertices]

n=21
base=[[0]*n for _ in range(n)]
pts={3:[(0,14),(3,17),(5,9),(6,10),(6,13),(8,15),(8,17)],6:[(2,3),(17,3)],1:[(2,7),(17,7)],7:[(2,6)],4:[(3,2)],8:[(13,10),(15,16),(17,13)]}
for color,ps in pts.items():
 for r,c in ps: base[r][c]=color
# connect all same-color pairs on 8-direction lines
out=[row[:] for row in base]
for color,ps in pts.items():
 for i,(r1,c1) in enumerate(ps):
  for r2,c2 in ps[i+1:]:
   dr,dc=r2-r1,c2-c1
   if dr==0 or dc==0 or abs(dr)==abs(dc):
    steps=max(abs(dr),abs(dc))
    for k in range(steps+1):
     out[r1+(0 if dr==0 else (1 if dr>0 else -1)*k)][c1+(0 if dc==0 else (1 if dc>0 else -1)*k)]=color
print('\n'.join(' '.join(map(str,row)) for row in out))
